# -*- coding: utf-8 -*-
import json, sys
sys.stdout.reconfigure(encoding='utf-8')
ENT = []
def E(id, he, en, desc, kind, parent, keys, country=None, no_wd=False, alt=None):
    d = {'id': id, 'he': he, 'en': en, 'desc': desc, 'kind': kind}
    if alt: d['en_alt'] = alt
    if parent: d['parent'] = parent
    if country: d['country'] = country
    if no_wd: d['no_wd'] = True
    d['keys'] = keys.split('|') if keys else []
    ENT.append(d)

